import{E as e,F as t,q as n,w as r}from"./vue.runtime.esm-bundler-DZZTqpJU.js";t();var i={class:`markdown-body`},a={__name:`vim-memo.content`,setup(t,{expose:a}){return a({frontmatter:{}}),(t,a)=>(n(),r(`div`,i,[...a[0]||=[e(`<p><strong>Vim</strong> is a modal editor: keys mean different things depending on the mode you are in. Most commands compose as <strong>count + operator + motion</strong> — <code>3dw</code> deletes three words, <code>d$</code> deletes to the end of the line — so learning a new motion instantly upgrades every operator you already know.</p><blockquote><p>💡 New to Vim? Run <code>vimtutor</code> in a terminal — 30 minutes, and the rest of this sheet starts making sense.</p></blockquote><h2>🚦 Modes</h2><table><thead><tr><th>Mode</th><th>Enter with</th><th>Leave with</th><th>For</th></tr></thead><tbody><tr><td>Normal</td><td><code>Esc</code> (or <code>Ctrl-[</code>)</td><td>—</td><td>Moving and running commands</td></tr><tr><td>Insert</td><td><code>i</code> <code>a</code> <code>o</code> <code>I</code> <code>A</code> <code>O</code></td><td><code>Esc</code></td><td>Typing text</td></tr><tr><td>Visual</td><td><code>v</code> <code>V</code> <code>Ctrl-v</code></td><td><code>Esc</code></td><td>Selecting text</td></tr><tr><td>Command-line</td><td><code>:</code> <code>/</code> <code>?</code></td><td><code>Enter</code> or <code>Esc</code></td><td>Ex commands and searches</td></tr><tr><td>Replace</td><td><code>R</code></td><td><code>Esc</code></td><td>Overtyping</td></tr></tbody></table><h2>🧭 Cursor Movement</h2><table><thead><tr><th>Key</th><th>Moves to</th></tr></thead><tbody><tr><td><code>h</code> <code>j</code> <code>k</code> <code>l</code></td><td>Left, down, up, right</td></tr><tr><td><code>w</code> / <code>W</code></td><td>Start of the next word / WORD (WORD ignores punctuation)</td></tr><tr><td><code>e</code> / <code>E</code></td><td>End of the next word / WORD</td></tr><tr><td><code>b</code> / <code>B</code></td><td>Start of the previous word / WORD</td></tr><tr><td><code>ge</code> / <code>gE</code></td><td>End of the previous word / WORD</td></tr><tr><td><code>0</code></td><td>First column of the line</td></tr><tr><td><code>^</code></td><td>First non-blank character</td></tr><tr><td><code>$</code></td><td>End of the line</td></tr><tr><td><code>g_</code></td><td>Last non-blank character</td></tr><tr><td><code>f&lt;char&gt;</code> / <code>F&lt;char&gt;</code></td><td>Next / previous occurrence of a character on the line</td></tr><tr><td><code>t&lt;char&gt;</code> / <code>T&lt;char&gt;</code></td><td>Just before the next / after the previous occurrence</td></tr><tr><td><code>;</code> / <code>,</code></td><td>Repeat the last <code>f</code>/<code>t</code> forwards / backwards</td></tr><tr><td><code>}</code> / <code>{</code></td><td>Next / previous paragraph</td></tr><tr><td><code>)</code> / <code>(</code></td><td>Next / previous sentence</td></tr><tr><td><code>gg</code> / <code>G</code></td><td>First / last line of the file</td></tr><tr><td><code>&lt;n&gt;G</code> or <code>:&lt;n&gt;</code></td><td>Line <code>n</code></td></tr><tr><td><code>H</code> <code>M</code> <code>L</code></td><td>Top, middle, bottom of the screen</td></tr><tr><td><code>Ctrl-d</code> / <code>Ctrl-u</code></td><td>Half a page down / up</td></tr><tr><td><code>Ctrl-f</code> / <code>Ctrl-b</code></td><td>A full page down / up</td></tr><tr><td><code>zz</code> <code>zt</code> <code>zb</code></td><td>Scroll so the cursor line is centred / at the top / at the bottom</td></tr><tr><td><code>%</code></td><td>The matching bracket, brace or parenthesis</td></tr><tr><td><code>Ctrl-o</code> / <code>Ctrl-i</code></td><td>Back / forward through the jump list</td></tr><tr><td><code>g;</code> / <code>g,</code></td><td>Back / forward through the change list</td></tr><tr><td><code>&#39;&#39;</code> / <code>\`\`</code></td><td>Back to where the last jump started</td></tr></tbody></table><h2>✏️ Entering Insert Mode</h2><table><thead><tr><th>Key</th><th>Starts typing</th></tr></thead><tbody><tr><td><code>i</code> / <code>I</code></td><td>Before the cursor / at the first non-blank character</td></tr><tr><td><code>a</code> / <code>A</code></td><td>After the cursor / at the end of the line</td></tr><tr><td><code>o</code> / <code>O</code></td><td>On a new line below / above</td></tr><tr><td><code>s</code> / <code>S</code></td><td>Deleting the character / the whole line first</td></tr><tr><td><code>cc</code></td><td>Replacing the whole line</td></tr><tr><td><code>C</code></td><td>Replacing from the cursor to the end of the line</td></tr><tr><td><code>gi</code></td><td>Where you last left insert mode</td></tr><tr><td><code>Ctrl-o</code></td><td>Run one normal-mode command, then return to insert</td></tr></tbody></table><h2>🔧 Operators &amp; Text Objects</h2><p>An operator waits for a motion or a text object. Doubling the operator (<code>dd</code>, <code>yy</code>, <code>&gt;&gt;</code>) applies it to the whole line.</p><table><thead><tr><th>Operator</th><th>Does</th></tr></thead><tbody><tr><td><code>d</code></td><td>Delete (into a register)</td></tr><tr><td><code>c</code></td><td>Change — delete, then insert</td></tr><tr><td><code>y</code></td><td>Yank (copy)</td></tr><tr><td><code>&gt;</code> / <code>&lt;</code></td><td>Indent / unindent</td></tr><tr><td><code>=</code></td><td>Re-indent</td></tr><tr><td><code>gu</code> / <code>gU</code> / <code>g~</code></td><td>Lower-case / upper-case / toggle case</td></tr><tr><td><code>gq</code></td><td>Reformat to <code>textwidth</code></td></tr></tbody></table><table><thead><tr><th>Text object</th><th>Selects</th></tr></thead><tbody><tr><td><code>iw</code> / <code>aw</code></td><td>Inner word / a word plus its trailing space</td></tr><tr><td><code>is</code> / <code>as</code></td><td>Sentence</td></tr><tr><td><code>ip</code> / <code>ap</code></td><td>Paragraph</td></tr><tr><td><code>i&quot;</code> <code>a&quot;</code></td><td>Inside / including the double quotes</td></tr><tr><td><code>i&#39;</code> <code>a&#39;</code></td><td>Inside / including the single quotes</td></tr><tr><td><code>i(</code> <code>a(</code></td><td>Inside / including the parentheses (also <code>ib</code>, <code>ab</code>)</td></tr><tr><td><code>i{</code> <code>a{</code></td><td>Inside / including the braces (also <code>iB</code>, <code>aB</code>)</td></tr><tr><td><code>i[</code> <code>a[</code></td><td>Inside / including the brackets</td></tr><tr><td><code>i&lt;</code> <code>a&lt;</code></td><td>Inside / including the angle brackets</td></tr><tr><td><code>it</code> / <code>at</code></td><td>Inside / including an HTML or XML tag</td></tr></tbody></table><pre><code class="language-text">ciw     change the word under the cursor
ci&quot;     change everything inside the quotes
da(     delete the parentheses and their contents
yi{     yank the body of a block
2dd     delete two lines
d3w     delete three words
&gt;ap     indent the whole paragraph
</code></pre><h2>✂️ Editing</h2><table><thead><tr><th>Key</th><th>Does</th></tr></thead><tbody><tr><td><code>x</code> / <code>X</code></td><td>Delete the character under / before the cursor</td></tr><tr><td><code>r&lt;char&gt;</code></td><td>Replace one character, staying in normal mode</td></tr><tr><td><code>R</code></td><td>Overtype until <code>Esc</code></td></tr><tr><td><code>~</code></td><td>Toggle the case of one character</td></tr><tr><td><code>J</code> / <code>gJ</code></td><td>Join the next line, with / without a space</td></tr><tr><td><code>u</code> / <code>Ctrl-r</code></td><td>Undo / redo</td></tr><tr><td><code>U</code></td><td>Undo every change on the current line</td></tr><tr><td><code>.</code></td><td>Repeat the last change — the most valuable key in Vim</td></tr><tr><td><code>Ctrl-a</code> / <code>Ctrl-x</code></td><td>Increment / decrement the number under the cursor</td></tr><tr><td><code>&gt;&gt;</code> / <code>&lt;&lt;</code></td><td>Indent / unindent the line</td></tr><tr><td><code>==</code></td><td>Re-indent the line</td></tr><tr><td><code>:earlier 10m</code> / <code>:later 5m</code></td><td>Move through the undo tree by time</td></tr></tbody></table><h2>📋 Copy, Paste &amp; Registers</h2><table><thead><tr><th>Key</th><th>Does</th></tr></thead><tbody><tr><td><code>yy</code> (or <code>Y</code>)</td><td>Yank the line</td></tr><tr><td><code>y&lt;motion&gt;</code></td><td>Yank what the motion covers</td></tr><tr><td><code>p</code> / <code>P</code></td><td>Paste after / before the cursor</td></tr><tr><td><code>]p</code></td><td>Paste and match the current indentation</td></tr><tr><td><code>dd</code> / <code>D</code></td><td>Delete the line / to the end of the line</td></tr><tr><td><code>&quot;ayy</code> / <code>&quot;ap</code></td><td>Yank into and paste from register <code>a</code></td></tr><tr><td><code>&quot;+y</code> / <code>&quot;+p</code></td><td>Yank to and paste from the system clipboard</td></tr><tr><td><code>&quot;0p</code></td><td>Paste the last <strong>yank</strong> (never overwritten by deletes)</td></tr><tr><td><code>:registers</code></td><td>Show every register</td></tr><tr><td><code>xp</code> / <code>ddp</code></td><td>Swap two characters / two lines</td></tr></tbody></table><blockquote><p>⚠️ In Vim, deleting also <em>yanks</em> — <code>dd</code> overwrites the unnamed register. Use <code>&quot;0p</code> to paste what you last copied, or yank into a named register first.</p></blockquote><h2>🔍 Search &amp; Replace</h2><table><thead><tr><th>Command</th><th>Does</th></tr></thead><tbody><tr><td><code>/pattern</code> / <code>?pattern</code></td><td>Search forwards / backwards</td></tr><tr><td><code>n</code> / <code>N</code></td><td>Next / previous match</td></tr><tr><td><code>*</code> / <code>#</code></td><td>Search for the word under the cursor, forwards / backwards</td></tr><tr><td><code>:noh</code></td><td>Clear the search highlighting</td></tr><tr><td><code>:s/old/new/</code></td><td>Replace the first match on the line</td></tr><tr><td><code>:s/old/new/g</code></td><td>Replace every match on the line</td></tr><tr><td><code>:%s/old/new/g</code></td><td>Replace throughout the file</td></tr><tr><td><code>:%s/old/new/gc</code></td><td>…asking for confirmation on each</td></tr><tr><td><code>:%s/old/new/gi</code></td><td>…ignoring case</td></tr><tr><td><code>:&#39;&lt;,&#39;&gt;s/old/new/g</code></td><td>Only inside the visual selection</td></tr><tr><td><code>:%s/\\&lt;word\\&gt;/new/g</code></td><td>Whole words only</td></tr><tr><td><code>&amp;</code></td><td>Repeat the last substitution on this line</td></tr></tbody></table><h3>The global command</h3><p><code>:g</code> runs an Ex command on every line matching a pattern — the power tool of Vim.</p><pre><code class="language-text">:g/TODO/d           delete every line containing TODO
:v/keep/d           delete every line NOT containing &#39;keep&#39; (:v is :g!)
:g/^$/d             delete all blank lines
:g/error/normal A;  append a semicolon to every matching line
:g/pattern/t$       copy matching lines to the end of the file
:g/pattern/m0       move matching lines to the top (reverses their order)
</code></pre><h2>🎨 Visual Mode</h2><table><thead><tr><th>Key</th><th>Does</th></tr></thead><tbody><tr><td><code>v</code></td><td>Character-wise selection</td></tr><tr><td><code>V</code></td><td>Line-wise selection</td></tr><tr><td><code>Ctrl-v</code></td><td>Block (column) selection</td></tr><tr><td><code>gv</code></td><td>Reselect the previous selection</td></tr><tr><td><code>o</code></td><td>Jump to the other end of the selection</td></tr><tr><td><code>d</code> / <code>y</code> / <code>c</code></td><td>Delete, yank or change the selection</td></tr><tr><td><code>&gt;</code> / <code>&lt;</code></td><td>Indent / unindent the selection</td></tr><tr><td><code>u</code> / <code>U</code> / <code>~</code></td><td>Lower-case, upper-case, toggle</td></tr><tr><td><code>:&#39;&lt;,&#39;&gt;</code></td><td>Run an Ex command over the selection</td></tr></tbody></table><pre><code class="language-text">Ctrl-v, select lines, I, type, Esc     insert the same text on every line
Ctrl-v, select lines, $, A, type, Esc  append at the end of every line
Ctrl-v, select, d                      delete a rectangular block
</code></pre><h2>🔖 Marks &amp; Jumps</h2><table><thead><tr><th>Key</th><th>Does</th></tr></thead><tbody><tr><td><code>m&lt;a-z&gt;</code></td><td>Set a mark in this file</td></tr><tr><td><code>m&lt;A-Z&gt;</code></td><td>Set a global mark, across files</td></tr><tr><td><code>\`a</code></td><td>Jump to mark <code>a</code>, exact position</td></tr><tr><td><code>&#39;a</code></td><td>Jump to the start of the line holding mark <code>a</code></td></tr><tr><td><code>\`.</code></td><td>Jump to the position of the last edit</td></tr><tr><td><code>:marks</code></td><td>List every mark</td></tr><tr><td><code>:delmarks a</code></td><td>Delete a mark</td></tr></tbody></table><h2>🎬 Macros</h2><table><thead><tr><th>Key</th><th>Does</th></tr></thead><tbody><tr><td><code>q&lt;a-z&gt;</code></td><td>Start recording into a register</td></tr><tr><td><code>q</code></td><td>Stop recording</td></tr><tr><td><code>@a</code></td><td>Play the macro back</td></tr><tr><td><code>@@</code></td><td>Replay the last macro</td></tr><tr><td><code>10@a</code></td><td>Run it ten times</td></tr><tr><td><code>:%normal @a</code></td><td>Run it on every line of the file</td></tr></tbody></table><h2>📂 Files, Buffers, Windows &amp; Tabs</h2><table><thead><tr><th>Command</th><th>Does</th></tr></thead><tbody><tr><td><code>:e &lt;file&gt;</code></td><td>Open a file</td></tr><tr><td><code>:e!</code></td><td>Reload, discarding changes</td></tr><tr><td><code>:w</code> / <code>:w &lt;file&gt;</code></td><td>Save / save as</td></tr><tr><td><code>:wa</code></td><td>Save every changed buffer</td></tr><tr><td><code>:q</code> / <code>:q!</code></td><td>Quit / quit without saving</td></tr><tr><td><code>:wq</code> or <code>:x</code> or <code>ZZ</code></td><td>Save and quit</td></tr><tr><td><code>ZQ</code></td><td>Quit without saving</td></tr><tr><td><code>:ls</code> / <code>:buffers</code></td><td>List the open buffers</td></tr><tr><td><code>:b &lt;n&gt;</code> / <code>:b &lt;name&gt;</code></td><td>Switch to a buffer</td></tr><tr><td><code>:bn</code> / <code>:bp</code> / <code>:bd</code></td><td>Next / previous / delete buffer</td></tr><tr><td><code>:sp</code> / <code>:vsp</code></td><td>Split horizontally / vertically</td></tr><tr><td><code>Ctrl-w h j k l</code></td><td>Move to the window in that direction</td></tr><tr><td><code>Ctrl-w w</code></td><td>Cycle through the windows</td></tr><tr><td><code>Ctrl-w q</code> / <code>Ctrl-w o</code></td><td>Close this window / close all the others</td></tr><tr><td><code>Ctrl-w =</code></td><td>Make all windows the same size</td></tr><tr><td><code>Ctrl-w +</code> / <code>-</code> / <code>&lt;</code> / <code>&gt;</code></td><td>Resize the window</td></tr><tr><td><code>:tabnew &lt;file&gt;</code></td><td>Open a new tab</td></tr><tr><td><code>gt</code> / <code>gT</code></td><td>Next / previous tab</td></tr><tr><td><code>:tabc</code> / <code>:tabo</code></td><td>Close this tab / close all the others</td></tr><tr><td><code>:r &lt;file&gt;</code> / <code>:r !cmd</code></td><td>Read a file, or a command’s output, into the buffer</td></tr><tr><td><code>:!&lt;cmd&gt;</code></td><td>Run a shell command</td></tr><tr><td><code>:%!&lt;cmd&gt;</code></td><td>Filter the whole buffer through a command</td></tr><tr><td><code>:w !sudo tee %</code></td><td>Save a file you opened without permission</td></tr></tbody></table><h2>📑 Folding</h2><table><thead><tr><th>Key</th><th>Does</th></tr></thead><tbody><tr><td><code>zf&lt;motion&gt;</code></td><td>Create a fold</td></tr><tr><td><code>za</code> / <code>zA</code></td><td>Toggle this fold / recursively</td></tr><tr><td><code>zo</code> / <code>zc</code></td><td>Open / close this fold</td></tr><tr><td><code>zR</code> / <code>zM</code></td><td>Open / close every fold</td></tr><tr><td><code>zj</code> / <code>zk</code></td><td>Move to the next / previous fold</td></tr></tbody></table><h2>🧩 Completion &amp; Spelling</h2><table><thead><tr><th>Key</th><th>Does</th></tr></thead><tbody><tr><td><code>Ctrl-n</code> / <code>Ctrl-p</code></td><td>Complete a word from the open buffers</td></tr><tr><td><code>Ctrl-x Ctrl-f</code></td><td>Complete a file path</td></tr><tr><td><code>Ctrl-x Ctrl-l</code></td><td>Complete a whole line</td></tr><tr><td><code>Ctrl-x Ctrl-o</code></td><td>Omni-completion (language-aware)</td></tr><tr><td><code>:set spell spelllang=en_us</code></td><td>Turn spell checking on</td></tr><tr><td><code>]s</code> / <code>[s</code></td><td>Next / previous misspelling</td></tr><tr><td><code>z=</code></td><td>Suggestions for the word under the cursor</td></tr><tr><td><code>zg</code> / <code>zw</code></td><td>Add to the dictionary / mark as wrong</td></tr></tbody></table><h2>🧵 Quickfix &amp; Diff</h2><table><thead><tr><th>Command</th><th>Does</th></tr></thead><tbody><tr><td><code>:make</code> / <code>:grep &lt;pat&gt;</code></td><td>Fill the quickfix list</td></tr><tr><td><code>:copen</code> / <code>:cclose</code></td><td>Open / close the quickfix window</td></tr><tr><td><code>:cn</code> / <code>:cp</code></td><td>Jump to the next / previous entry</td></tr><tr><td><code>:cfirst</code> / <code>:clast</code></td><td>First / last entry</td></tr><tr><td><code>vimdiff a b</code></td><td>Open two files in diff mode</td></tr><tr><td><code>]c</code> / <code>[c</code></td><td>Next / previous difference</td></tr><tr><td><code>do</code> / <code>dp</code></td><td>Obtain / put the change under the cursor</td></tr><tr><td><code>:diffupdate</code></td><td>Refresh the diff</td></tr></tbody></table><h2>⚙️ Handy <code>:set</code> Options</h2><table><thead><tr><th>Option</th><th>Effect</th></tr></thead><tbody><tr><td><code>:set nu</code> / <code>:set nonu</code></td><td>Show / hide line numbers</td></tr><tr><td><code>:set rnu</code></td><td>Relative line numbers — makes <code>5j</code> obvious</td></tr><tr><td><code>:set ic</code> / <code>:set noic</code></td><td>Ignore case when searching</td></tr><tr><td><code>:set is</code> / <code>:set hls</code></td><td>Incremental search / highlight matches</td></tr><tr><td><code>:set wrap</code> / <code>:set nowrap</code></td><td>Soft-wrap long lines</td></tr><tr><td><code>:set list</code></td><td>Show tabs and trailing whitespace</td></tr><tr><td><code>:set paste</code></td><td>Stop auto-indent mangling pasted text</td></tr><tr><td><code>:set ft=&lt;type&gt;</code></td><td>Force a file type</td></tr><tr><td><code>:set sw=4 ts=4 et</code></td><td>Four-space indentation, spaces not tabs</td></tr><tr><td><code>:syntax on</code></td><td>Syntax highlighting</td></tr></tbody></table><h2>📄 A Starting <code>~/.vimrc</code></h2><pre><code class="language-vim">set nocompatible
syntax on
filetype plugin indent on

set number relativenumber
set incsearch hlsearch ignorecase smartcase
set expandtab shiftwidth=2 tabstop=2
set scrolloff=5
set hidden
set undofile
set clipboard=unnamedplus

&quot; a leader key, and a few mappings that pay for themselves
let mapleader = &quot; &quot;
nnoremap &lt;leader&gt;w :w&lt;CR&gt;
nnoremap &lt;leader&gt;/ :nohlsearch&lt;CR&gt;
nnoremap &lt;C-h&gt; &lt;C-w&gt;h
nnoremap &lt;C-j&gt; &lt;C-w&gt;j
nnoremap &lt;C-k&gt; &lt;C-w&gt;k
nnoremap &lt;C-l&gt; &lt;C-w&gt;l
</code></pre><blockquote><p>ℹ️ Mappings that start with <code>&lt;leader&gt;</code> are <strong>your</strong> configuration, not built-in Vim. If a leader shortcut on someone else’s cheat sheet does nothing, that is why.</p></blockquote><h2>📚 Resources</h2><ul><li><code>vimtutor</code> — the built-in 30-minute tutorial</li><li><code>:help &lt;topic&gt;</code> — Vim’s own documentation, and it is excellent</li><li><a href="https://vimhelp.org/">Vim documentation</a></li><li><a href="https://vim-adventures.com/">Vim Adventures — learn by playing</a></li><li><a href="https://pragprog.com/titles/dnvim2/practical-vim-second-edition/">Practical Vim (book)</a></li></ul>`,45)]]))}};export{a as default};